import argparse
import hashlib
import json
import os
from pathlib import Path
import shlex
import shutil
import signal
import subprocess
import sys
import tempfile

NAMES=('.bash_profile','.bashrc','.bash_login','.profile','system.bashrc','noninteractive.env')


def native(home,flags,trace,envrc=False):
    serializer="import json,os,sys;print(json.dumps({'x':sys.argv[1],'scope':sys.argv[2],'login_flag':sys.argv[3],'interactive':'i' in sys.argv[4],'login_shell':sys.argv[5]=='1','child_x':os.getenv('x'),'child_scope':os.getenv('APP_SCOPE'),'uid':os.geteuid(),'home':os.getenv('HOME')}))"
    command='if shopt -q login_shell;then login=1;else login=0;fi\n'+shlex.quote(sys.executable)+' -c '+shlex.quote(serializer)+' "${x-unset}" "${APP_SCOPE-unset}" "${LOGIN_FLAG-unset}" "$-" "$login"'
    environment={'HOME':str(home),'PATH':'/usr/bin:/bin','LANG':'C.UTF-8','TERM':'dumb','HISTFILE':'/dev/null',
                 'OPSFORGE_TRACE':str(trace),'PYTHONDONTWRITEBYTECODE':'1'}
    if envrc:environment['BASH_ENV']=str(home/'noninteractive.env')
    process=subprocess.Popen(['/bin/bash',*flags,command],cwd=home,env=environment,stdin=subprocess.DEVNULL,
                             stdout=subprocess.PIPE,stderr=subprocess.PIPE,start_new_session=True)
    try:stdout,stderr=process.communicate(timeout=2)
    except BaseException:
        try:os.killpg(process.pid,signal.SIGKILL)
        except ProcessLookupError:pass
        process.communicate(timeout=1)
        raise
    if process.returncode!=0:raise ValueError('native startup failed')
    value=json.loads(stdout.decode('utf8'))
    value['trace']=trace.read_text().splitlines() if trace.exists() else []
    value['exit_status']=process.returncode
    return value


def _collect(home):
    home=Path(os.path.abspath(home))
    hashes={name:hashlib.sha256((home/name).read_bytes()).hexdigest() for name in NAMES}
    with tempfile.TemporaryDirectory(prefix='.probe-',dir=home.parent) as folder:
        temporary=Path(folder);rows={}
        for mode,flags,envrc in [('login',['--login','-c'],False),('interactive_login',['--login','-i','-c'],False),
                                ('interactive',['-i','-c'],False),('plain',['-c'],False),('envrc',['-c'],True)]:
            rows[mode]=native(home,flags,temporary/(mode+'.trace'),envrc)
        for mode,missing in [('bash_login',('.bash_profile',)),('profile',('.bash_profile','.bash_login')),
                             ('bare',('.bash_profile','.bash_login','.profile'))]:
            clone=temporary/mode;clone.mkdir(mode=0o700)
            for name in NAMES:
                if name not in missing:shutil.copyfile(home/name,clone/name)
            rows[mode]=native(clone,['--login','-c'],temporary/(mode+'.trace'))
    return {'schema':1,'home':str(home),'config_sha256':hashes,'modes':rows}


def collect(home):
    inherited=os.umask(0o077)
    try:return _collect(home)
    finally:os.umask(inherited)


def validate(report,value,scope,label):
    if type(report.get('schema')) is not int or report['schema']!=1 or set(report['modes'])!={'login','interactive_login','interactive','plain','envrc','bash_login','profile','bare'}:
        raise ValueError('probe matrix')
    for mode,row in report['modes'].items():
        if mode in ('login','interactive_login'):expected=(str(value),scope,'yes',['profile','global',label])
        elif mode=='interactive':expected=(str(value),scope,'unset',['global',label])
        elif mode=='envrc':expected=('8','envrc','unset',['envrc'])
        elif mode=='bash_login':expected=('4','login-fallback','unset',['bash_login'])
        elif mode=='profile':expected=('3','profile-fallback','unset',['profile_fallback'])
        else:expected=('unset','unset','unset',[])
        if (row['x'],row['scope'],row['login_flag'],row['trace'])!=expected:raise ValueError('startup precedence mismatch: '+mode)
        if row['interactive'] is not (mode in ('interactive_login','interactive')) or row['login_shell'] is not (mode in ('login','interactive_login','bash_login','profile','bare')):
            raise ValueError('native invocation flags')
        if row['child_x'] is not None or row['child_scope']!=(None if row['scope']=='unset' else row['scope']) or row['uid']!=os.geteuid():
            raise ValueError('shell variables versus exported environment')
        if row['exit_status']!=0:raise ValueError('startup exit')


def main():
    parser=argparse.ArgumentParser();parser.add_argument('--home',required=True);parser.add_argument('--output',required=True);args=parser.parse_args()
    inherited=os.umask(0o077);temporary=None
    try:
        if os.path.lexists(args.output):raise ValueError('output exists')
        report=collect(args.home)
        descriptor,temporary=tempfile.mkstemp(prefix='.probe-report-',dir=Path(args.output).parent)
        with os.fdopen(descriptor,'w',encoding='utf8') as stream:
            json.dump(report,stream,sort_keys=True);stream.flush();os.fsync(stream.fileno())
        os.link(temporary,args.output)
    except (OSError,ValueError,KeyError,subprocess.TimeoutExpired):
        print('startup probe failed',file=sys.stderr);return 2
    finally:
        if temporary is not None and os.path.exists(temporary):os.unlink(temporary)
        os.umask(inherited)
    print(json.dumps({'measured':True,'modes':len(report['modes'])}));return 0


