import argparse
import hashlib
import json
import os
from pathlib import Path
import secrets
import shutil
import signal
import subprocess
import sys
import time
from probe_home import NAMES,collect,validate


class Interrupted(Exception):
    def __init__(self,code):self.code=code


def interrupted(signum,frame):raise Interrupted(130 if signum==signal.SIGINT else 143)


def atomic(path,value):
    temporary=path.parent/('.metadata-'+secrets.token_hex(8))
    try:
        with temporary.open('x') as stream:json.dump(value,stream,sort_keys=True);stream.flush();os.fsync(stream.fileno())
        os.replace(temporary,path)
    finally:
        if temporary.exists():temporary.unlink()


def hashes(home):
    if set(path.name for path in home.iterdir())!=set(NAMES):raise ValueError('unexpected startup files')
    if any((home/name).is_symlink() for name in NAMES):raise ValueError('startup symlink')
    return {name:hashlib.sha256((home/name).read_bytes()).hexdigest() for name in NAMES}


def link(state,target):
    temporary=state/('.active-'+secrets.token_hex(8))
    try:temporary.symlink_to(target);os.replace(temporary,state/'active')
    finally:
        if os.path.lexists(temporary):temporary.unlink()


def audit(state,phase,report):
    atomic(state/'evidence'/(str(time.monotonic_ns())+'-'+phase+'.json'),{'phase':phase,'report':report})


def prepare(state,fixture):
    if os.path.lexists(state):raise ValueError('state exists')
    created=False
    try:
        state.mkdir(mode=0o700);created=True;state.chmod(0o700)
        for name in ('versions','evidence'):(state/name).mkdir(mode=0o700);(state/name).chmod(0o700)
        baseline=state/'versions/baseline';baseline.mkdir(mode=0o700);baseline.chmod(0o700)
        if set(path.name for path in fixture.iterdir())!=set(NAMES):raise ValueError('fixture file set')
        for name in NAMES:
            source=fixture/name
            if source.is_symlink() or not source.is_file():raise ValueError('fixture must be regular files')
            shutil.copyfile(source,baseline/name);(baseline/name).chmod(0o600)
        report=collect(baseline);validate(report,4,'baseline','baseline')
        atomic(state/'baseline.json',hashes(baseline));link(state,'versions/baseline');audit(state,'prepare',report)
    except BaseException:
        if created:shutil.rmtree(state)
        raise


def stage(state):
    if (state/'versions/candidate').exists():raise ValueError('candidate already exists')
    temporary=state/'versions'/('.candidate-'+secrets.token_hex(8))
    try:
        baseline=state/'versions/baseline'
        if hashes(baseline)!=json.loads((state/'baseline.json').read_text()):raise ValueError('baseline altered')
        shutil.copytree(baseline,temporary);temporary.chmod(0o700)
        for source,target in [('profile.bash','.bash_profile'),('interactive.bash','.bashrc')]:
            shutil.copyfile(Path(__file__).with_name(source),temporary/target);(temporary/target).chmod(0o600)
        for name in NAMES:
            result=subprocess.run(['/bin/bash','-n',str(temporary/name)],capture_output=True,timeout=2)
            if result.returncode:raise ValueError('candidate syntax')
        report=collect(temporary);validate(report,6,'user','user')
        candidate_hashes=hashes(temporary);os.replace(temporary,state/'versions/candidate')
        atomic(state/'candidate.json',candidate_hashes);audit(state,'stage',report)
    finally:
        if temporary.exists():shutil.rmtree(temporary)


def activate(state):
    candidate=state/'versions/candidate'
    if hashes(candidate)!=json.loads((state/'candidate.json').read_text()):raise ValueError('candidate altered after stage')
    report=collect(candidate);validate(report,6,'user','user')
    # A repeated activation may already point at candidate. The recovery
    # generation is the approved baseline, never the now-failing candidate.
    previous='versions/baseline'
    try:
        link(state,'versions/candidate')
        live=collect(state/'active');validate(live,6,'user','user')
        audit(state,'activate',live)
    except BaseException:
        link(state,previous)
        restored=collect(state/'active');validate(restored,4,'baseline','baseline')
        audit(state,'activate-restored',restored)
        raise


def rollback(state):
    baseline=state/'versions/baseline'
    if hashes(baseline)!=json.loads((state/'baseline.json').read_text()):raise ValueError('baseline altered')
    link(state,'versions/baseline')
    report=collect(state/'active');validate(report,4,'baseline','baseline');audit(state,'rollback',report)


def main():
    parser=argparse.ArgumentParser();parser.add_argument('phase',choices=['prepare','stage','activate','rollback']);parser.add_argument('--state',required=True);parser.add_argument('--fixture');args=parser.parse_args()
    state=Path(os.path.abspath(args.state));mask=os.umask(0o077)
    signal.signal(signal.SIGTERM,interrupted);signal.signal(signal.SIGINT,interrupted)
    try:
        if state.is_symlink():raise ValueError('state symlink')
        if args.phase=='prepare':
            if not args.fixture:raise ValueError('fixture required')
            prepare(state,Path(args.fixture))
        else:
            if not state.is_dir() or os.readlink(state/'active') not in ('versions/baseline','versions/candidate'):raise ValueError('unmanaged state')
            {'stage':stage,'activate':activate,'rollback':rollback}[args.phase](state)
    except Interrupted as error:
        print('startup operation interrupted',file=sys.stderr);return error.code
    except (OSError,ValueError,KeyError,TypeError,subprocess.TimeoutExpired):
        print('startup operation failed',file=sys.stderr);return 2
    finally:os.umask(mask)
    print(json.dumps({'phase':args.phase,'active':os.readlink(state/'active')}));return 0


if __name__=='__main__':raise SystemExit(main())

